// End-to-end test for the NEXT wholly rebuilt, same-ABI resident library.
// This file calls the actual NativeBoundarySession factory and execute_live.
// It has NOT been executed against the old library and must never be linked to it.
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/kernel/native_initial_state.hpp"
#include "resident/kernel/world_codec.hpp"
#include "resident/kernel/world_timeline_codec.hpp"
#include "resident/kernel/exact_time_profile.hpp"
#include "resident/kernel/continuation_binding.hpp"
#include <picosha2.h>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;
Integer checks=0;
void check(bool okay,const StableId& why){++checks;if(!okay)throw std::runtime_error(why);}
template<class T>T must(Outcome<T> r,const StableId& why){check(r.ok,why+": "+r.error.original.code+" "+r.error.original.path);return std::move(r.value);}
void must(Status r,const StableId& why){check(r.ok,why+": "+r.error.original.code+" "+r.error.original.path);}
V obj(std::initializer_list<std::pair<StableId,V>> xs){return V{V::Dict(xs)};}
const V& field(const V& v,const StableId& key){auto* f=v.find(key);check(f!=nullptr,"missing DTO field "+key);return *f;}
StableId str(const V& v,const StableId& key){auto* p=field(v,key).as<StableId>();check(p!=nullptr,"string DTO field "+key);return *p;}
Integer integer(const V& v,const StableId& key){auto* p=field(v,key).as<Integer>();check(p!=nullptr,"integer DTO field "+key);return *p;}
bool okay(const V& v){const auto* p=v.find("ok");return p&&p->as<bool>()&&*p->as<bool>();}
WorldMoment moment(Integer tick,const char* n="0",const char* d="1"){return {tick,must(normalize_fraction(n,d),"canonical test fraction")};}
void check_moment(const V& v,const char* key,WorldMoment expected){auto encoded=must(encode_world_moment2(expected),"expected moment codec");check(compare_boundary(field(v,key),encoded).exact(),StableId{key}+" preserves exact typed moment");}
void check_units(const V& v,const char* key,const char* numerator){WorkUnits units{must(normalize_fraction(numerator,"1"),"expected work units")};check(compare_boundary(field(v,key),must(encode_work_units2(units),"expected WorkUnits codec")).exact(),StableId{key}+" typed WorkUnits preserved");}
CatalogIdentity catalog_identity(const V& input){CatalogIdentity id;id.content_id=str(input,"content_id");id.content_version=str(input,"content_version");id.content_digest=str(input,"content_digest");id.schema_sha256=str(input,"schema_sha256");id.ruleset_id="hanmo.native.local_society/1";id.artifact_sha256=picosha2::hash256_hex_string(must(render_boundary_json(input),"canonical authored fixture bytes"));id.module_versions={{"dynamic_world","local_society_v1"},{"local_economy","1"},{"organization","2"},{"affairs","1"},{"director","2"},{"regional_life","1"}};must(append_exact_time_modules(id),"explicit exact modules");return id;}
V identity_dto(const CatalogIdentity& id){V::Array modules;for(const auto& m:id.module_versions)modules.push_back(obj({{"name",V{m.first}},{"version",V{m.second}}}));return obj({{"content_id",V{id.content_id}},{"content_version",V{id.content_version}},{"content_digest",V{id.content_digest}},{"ruleset_id",V{id.ruleset_id}},{"schema_sha256",V{id.schema_sha256}},{"artifact_sha256",V{id.artifact_sha256}},{"module_versions",V{std::move(modules)}}});}
LiveOperationResult operation(ResidentReplaySession& session,LiveOperationKind kind,V payload){LiveOperation op;op.kind=kind;op.source=must(session.identity(),"actual session identity");op.payload=std::move(payload);auto r=must(session.execute_live(op),"real execute_live");check(okay(r.result),"real execute_live DTO success: "+(r.result.find("code")?str(r.result,"code"):"missing success"));return r;}
V query(ResidentReplaySession& session,const char* name,V args=obj({})){return operation(session,LiveOperationKind::query,obj({{"query_id",V{StableId{name}}},{"args",std::move(args)}})).result;}
LiveOperation command_request(ResidentReplaySession& session,const char* kind,V params){auto ctx=query(session,"command_context");LiveOperation op;op.kind=LiveOperationKind::command;op.source=must(session.identity(),"command identity");op.payload=obj({{"actor_id",V{StableId{"actor.player"}}},{"kind",V{StableId{kind}}},{"params",std::move(params)},{"request_seq",V{integer(ctx,"next_request_seq")}},{"expected_revision",V{integer(ctx,"revision")}}});return op;}
void command(ResidentReplaySession& session,const char* kind,V params){auto op=command_request(session,kind,std::move(params));auto actual=must(session.execute_live(op),"real command");check(okay(actual.result),"real command DTO succeeded");}
V begin(ResidentReplaySession& session,const StableId& run,const StableId& action,Integer budget,bool saved=false){return operation(session,LiveOperationKind::begin_run,obj({{"run_id",V{run}},{"actor_id",V{StableId{"actor.player"}}},{"action_id",V{action}},{"max_half_days",V{budget}},{"max_gross_outflow",V{Integer{100}}},{"resume_saved_scope",V{saved}}})).result;}
V grant(ResidentReplaySession& session,const StableId& run){return operation(session,LiveOperationKind::grant,obj({{"run_id",V{run}},{"permit_seq",V{Integer{1}}},{"grant_half_days",V{Integer{1}}}})).result;}
// Cold inspection reads an actual session checkpoint. It never advances test state.
std::unique_ptr<WorldBundle> read(ResidentReplaySession& session,std::shared_ptr<const PreparedCatalog> catalog){auto checkpoint=must(session.checkpoint(),"actual read checkpoint");auto seed=must(decode_world_checkpoint(checkpoint,*catalog),"actual cold decode");auto result=std::make_unique<WorldBundle>(std::move(catalog),std::move(seed));must(result->validate(),"whole cold closure");return result;}
}
int main(int argc,char** argv){try{
    check(argc==2,"frozen authored fixture path required");std::ifstream in(argv[1]);check(bool(in),"fixture readable");std::ostringstream text;text<<in.rdbuf();auto input=must(parse_boundary_json(text.str()),"authored fixture JSON");auto selected=catalog_identity(input);
    auto catalog=must(prepare_native_catalog(input,"engineering.exact_rest_only",selected),"prepare exact native catalog");
    auto session=create_resident_replay_session();check(bool(session),"real boundary factory");must(session->initialize_native(input,obj({{"scenario_id",V{StableId{"engineering.exact_rest_only"}}},{"world_seed",V{StableId{"exact-boundary-session"}}},{"expected_catalog_identity",identity_dto(selected)}})),"real boundary native initialize");
    const auto initial_checkpoint=must(session->checkpoint(),"initial genuine checkpoint");auto initial=read(*session,catalog);const auto initial_player_balance=initial->common.wallet("wallet.player")->balance;const auto initial_inn_balance=initial->common.wallet("wallet.inn")->balance;
    command(*session,"advance",obj({{"requested_to",must(encode_world_moment2(moment(0,"1","3")),"advance exact DTO")}}));
    auto rest=command_request(*session,"service",obj({{"activity",V{StableId{"rest"}}},{"context",obj({{"place_id",V{StableId{"west.inn"}}},{"provider_actor_id",V{StableId{"actor.innkeeper"}}},{"role_id",V{StableId{"role.inn"}}}})}}));
    auto submitted=must(session->execute_live(rest),"real rest submit");check(okay(submitted.result),"rest receipt succeeds");auto once=must(session->checkpoint(),"after real rest");auto replay=must(session->execute_live(rest),"same rest request replay");check(okay(replay.result)&&compare_boundary(replay.result,submitted.result).exact(),"same receipt replay");check(must(session->checkpoint(),"after replay")==once,"rest replay never charges twice");
    auto action=str(query(*session,"action_context"),"action_id");auto started=read(*session,catalog);check(started->common.wallet("wallet.player")->balance==initial_player_balance-20&&started->common.wallet("wallet.inn")->balance==initial_inn_balance+20,"original service fee charged and credited once");
    auto first=begin(*session,"boundary.scope.one",action,2);check_moment(first,"exact_source_moment",moment(0,"1","3"));check_units(first,"exact_spent_units","0");check_units(first,"exact_remaining_units","120");
    auto stepped=grant(*session,"boundary.scope.one");check(str(stepped,"stop")=="awaiting_permit","actual run parks after first grant");check_moment(stepped,"exact_source_moment",moment(1,"1","3"));check_units(stepped,"exact_spent_units","60");check_units(stepped,"exact_remaining_units","60");
    auto polled=query(*session,"run_progress",obj({{"run_id",V{StableId{"boundary.scope.one"}}}}));check(compare_boundary(polled,stepped).exact(),"public run_progress query retains exact DTO");auto mid=read(*session,catalog);check(mid->common.actor("actor.player")->hp==57,"rest body not applied early");
    auto state=query(*session,"continuation_state");const auto& scope=field(state,"continuation");check(integer(scope,"continuation_version")==2,"actual continuation projects version 2");check_moment(scope,"exact_source_moment",moment(1,"1","3"));check_moment(scope,"exact_started_at",moment(0,"1","3"));HalfDayDuration elapsed{must(normalize_fraction("1","1"),"elapsed one")};check(compare_boundary(field(scope,"exact_committed_duration"),must(encode_half_day_duration2(elapsed),"duration codec")).exact(),"actual committed duration typed DTO");const auto& started_source=field(scope,"action_started_source");check(str(started_source,"domain")=="growth"&&str(started_source,"kind")=="growth_fixed_service_boundary"&&integer(started_source,"schema")==1&&!str(started_source,"id").empty(),"actual Started source projected");
    auto saved=operation(*session,LiveOperationKind::checkpoint,obj({}));check(saved.checkpoint_bytes.has_value()&&saved.continuation_bytes.has_value(),"actual live checkpoint returns paired payloads");const auto& continuation=*saved.continuation_bytes;check(continuation.size()>5&&continuation[0]=='H'&&continuation[1]=='M'&&continuation[2]=='C'&&continuation[3]=='B'&&continuation[4]==2,"actual live writer emits HMCB version 2");auto decoded=must(unbind_continuation_checkpoint(continuation,*saved.checkpoint_bytes,engineering_slot_capacity_profile()),"actual HMCB2 unbind");check(decoded.continuation_version==2&&decoded.exact_source_moment.has_value(),"HMCB2 carries typed exact continuation");check(!unbind_continuation_checkpoint(continuation,initial_checkpoint,engineering_slot_capacity_profile()).ok,"HMCB2 rejects a genuine different checkpoint");check(!unbind_continuation_checkpoint(continuation,*saved.checkpoint_bytes).ok,"legacy two-argument reader refuses HMCB2");
    auto wrong=create_resident_replay_session();check(!wrong->initialize_checkpoint_with_continuation(input,initial_checkpoint,continuation).ok,"boundary cold install rejects wrong checkpoint pair");check(!wrong->identity().ok,"failed wrong pair leaves no installed world");
    auto restored=create_resident_replay_session();must(restored->initialize_checkpoint_with_continuation(input,*saved.checkpoint_bytes,continuation),"real boundary cold HMCB2 restore");auto recovered=query(*restored,"continuation_state");check_moment(field(recovered,"continuation"),"exact_source_moment",moment(1,"1","3"));check_moment(field(recovered,"continuation"),"exact_started_at",moment(0,"1","3"));
    auto next=begin(*restored,"boundary.scope.two",action,1,true);check_moment(next,"exact_source_moment",moment(1,"1","3"));auto done=grant(*restored,"boundary.scope.two");check(str(done,"stop")=="completed","real resumed rest completes");check_moment(done,"exact_source_moment",moment(2,"1","3"));
    auto end=read(*restored,catalog);check(end->common.actor("actor.player")->hp==92&&end->common.actor("actor.player")->fatigue==12&&end->common.state().actors.find("actor.player")->injury==0,"original rest body applied at exact due time");check(end->growth.fixed_service_boundaries.size()==2,"one genuine Started and Completed");check(end->actor_foundation->character_condition_extensions.applied_receipts.size()==1,"one genuine ConditionReceipt");check(end->common.wallet("wallet.player")->balance==initial_player_balance-20&&end->common.wallet("wallet.inn")->balance==initial_inn_balance+20,"cold resumed rest does not charge again");
    check(must(compare_world_moments(must(read_world_moment(end->common.tick(),*end->world_timeline),"actual end moment"),moment(2,"1","3")),"exact end compare")==0,"rest finishes at 2+1/3 without floor or ceil");
    std::cout<<"BOUNDARY_EXACT_SESSION_CHECKS="<<checks<<" FAILURES=0\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
